function item(size, brand, model, type, status, level, summary, sources, note = "", aliases = "") {
  return { size, brand, model, type, status, level, summary, sources, note, aliases };
}

function legacy(size, brand, model, type, sources, note = "") {
  const dimensions = size.replace("x", " × ");
  const catalogs = sources.map(({ title }) => title.split(" 磨料目录")[0]).join("、");
  return item(size, brand, model, type, "confirmed", "磨料目录",
    catalogs + "的适配表收录该型号，规格为 " + dimensions + " mm。", sources,
    note || "依据磨料厂家适配目录。购买前可对照手头设备的完整铭牌型号。");
}

function lead(size, brand, model, type, summary, sources, note, aliases) {
  return item(size, brand, model, type, "pending", "核实线索", summary, sources, note, aliases);
}

